/* Official TDS PDFs are generated by the authenticated API. */
(function () {
  "use strict";
  const PRODUCT = document.body.dataset.product;
  const API = "https://api.whitedotindia.in";
  const buttons = [...document.querySelectorAll("[data-download-tds]")];
  buttons.forEach(btn => { btn.hidden = true; });
  let product;
  let generation = 0;
  function token() { try { return localStorage.getItem("wd_admin_token"); } catch { return null; } }
  function hide() { buttons.forEach(btn => { btn.hidden = true; }); }
  async function refreshAccess() {
    const request = ++generation;
    hide();
    const jwt = token();
    if (!jwt || !product || product.tdsAvailable === false || !product.specs?.length) return;
    try {
      const res = await fetch(API + "/api/auth/me", { headers: { Authorization: "Bearer " + jwt }, cache: "no-store", signal: AbortSignal.timeout(10000) });
      if (!res.ok) return;
      const session = await res.json();
      if (request === generation && jwt === token() && session.success && session.data?.role === "SUPER_ADMIN") {
        buttons.forEach(btn => { btn.hidden = false; });
      }
    } catch { hide(); }
  }
  buttons.forEach(btn => btn.addEventListener("click", async event => {
    event.preventDefault();
    const jwt = token();
    if (!jwt || btn.hidden || btn.getAttribute("aria-busy") === "true") return;
    const original = btn.innerHTML;
    btn.setAttribute("aria-busy", "true");
    btn.innerHTML = "<span>Preparing TDS…</span>";
    try {
      const res = await fetch(API + "/api/case-study-tds/" + encodeURIComponent(PRODUCT), {
        headers: { Authorization: "Bearer " + jwt }, cache: "no-store", signal: AbortSignal.timeout(25000)
      });
      if (res.status === 401 || res.status === 403) { hide(); throw new Error("A current superadmin session is required to download TDS files."); }
      if (!res.ok || !res.headers.get("content-type")?.includes("application/pdf")) throw new Error("The TDS could not be prepared. Please try again.");
      const blob = await res.blob();
      if (jwt !== token()) { hide(); return; }
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = "White-Dot-TDS-" + PRODUCT.replace(/[^a-z0-9-]/gi, "-") + ".pdf";
      document.body.appendChild(link); link.click(); link.remove();
      setTimeout(() => URL.revokeObjectURL(url), 1000);
    } catch (error) { alert(error.message || "The TDS could not be prepared. Please try again."); }
    finally { btn.innerHTML = original; btn.removeAttribute("aria-busy"); }
  }));
  window.addEventListener("storage", event => { if (event.key === "wd_admin_token" || event.key === null) refreshAccess(); });
  window.addEventListener("focus", refreshAccess);
  fetch(new URL("./data/specs.json", document.baseURI), { cache: "no-cache" })
    .then(res => { if (!res.ok) throw new Error("Specifications unavailable"); return res.json(); })
    .then(db => {
      product = db.products[PRODUCT];
      if (!product) return;
      const host = document.querySelector("[data-tds-verified-slot]");
      const specs = product.specs || [];
      if (host && specs.length) {
        const count = specs.filter(s => s.verified).length;
        host.textContent = count + " of " + specs.length + (product.id === "bottleCap" || product.dataKind === "trial-workbook"
          ? " fields transcribed from the supplied trial workbook; not supplier-certified"
          : " fields verified from photo references or published supplier data");
      }
      return refreshAccess();
    }).catch(() => hide());
})();
